-- ============================================================
-- 漫思茶 RAG 知识库扩充（W3 评测集配套）
-- 目的：把 kb_chunk 从 6 条扩到 120+ 条，让 Recall@5 对照有统计意义
--       （知识库过小时检索几乎必然命中，数字会虚高、经不起追问）
-- 用法：
--   mysql -uroot -p123456 --default-character-set=utf8mb4 db_agent < kb_expand.sql
-- 说明：显式指定 id（100 起），避免与现有 1-6 冲突，且便于评测集标注 expected_chunk_ids
-- ============================================================

USE db_agent;

-- ---------- 文档：六个知识域 ----------
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `status` = VALUES(`status`);

