-- ---------- 校验 ----------
SELECT 'kb_document 总数' AS item, COUNT(*) AS cnt FROM kb_document
UNION ALL SELECT 'kb_chunk 总数', COUNT(*) FROM kb_chunk
UNION ALL SELECT '新入库文档数（3-8）', COUNT(*) FROM kb_document WHERE id BETWEEN 3 AND 8
UNION ALL SELECT '新知识块数（100+）', COUNT(*) FROM kb_chunk WHERE id >= 100;
