INSERT INTO `kb_document` (`id`, `title`, `source_type`, `status`) VALUES
  (3, '六大茶类详解', 'manual', 'embedded'),
  (4, '冲泡技艺与品鉴', 'manual', 'embedded'),
  (5, '茶叶选购与储存', 'manual', 'embedded'),
  (6, '茶器与养护', 'manual', 'embedded'),
  (7, '茶文化与历史', 'manual', 'embedded'),
  (8, '茶与健康', 'manual', 'embedded')
INSERT INTO `kb_chunk` (`id`, `document_id`, `content`, `token_count`, `chunk_index`) VALUES
(100, 3, '中国茶叶按加工工艺与发酵程度分为六大茶类：绿茶（不发酵）、白茶（微发酵）、黄茶（轻发酵）、青茶/乌龙茶（半发酵）、红茶（全发酵）、黑茶（后发酵）。发酵程度决定茶多酚氧化程度，进而决定汤色、香气与滋味走向。', 60, 0),
(101, 3, '绿茶属不发酵茶，鲜叶经杀青、揉捻、干燥而成。杀青通过高温钝化多酚氧化酶，保留大量茶多酚与叶绿素，因此汤色清绿、滋味鲜爽。代表茶有西湖龙井、洞庭碧螺春、黄山毛峰、信阳毛尖、太平猴魁。', 62, 1),
(102, 3, '西湖龙井属炒青绿茶，产于杭州西湖区。外形扁平挺直、光滑匀齐，色翠略黄似糙米色，香气清高持久带豆香或兰花香，滋味鲜爽甘醇，汤色清澈明亮，叶底嫩绿成朵。以狮峰、龙井、云栖、虎跑、梅家坞五地所产品质最佳，号称"狮龙云虎梅"。', 78, 2),
(103, 3, '洞庭碧螺春产于江苏苏州太湖洞庭东山与西山，属炒青绿茶。外形条索纤细卷曲如螺，满披白毫，冲泡后清香持久，滋味鲜醇甘厚，有"一嫩（芽叶嫩）三鲜（色鲜艳、香鲜浓、味鲜醇）"之誉。因茶树与果树间种，常带天然花果香。', 72, 3),
(104, 3, '黄山毛峰属烘青绿茶，产于安徽黄山。外形微卷似雀舌，色如象牙，带金黄色鱼叶（俗称"黄金片"），香气清鲜高长，滋味醇厚回甘，汤色清碧微黄。特级毛峰采一芽一叶初展，清明前后开采。', 62, 4),
(105, 3, '信阳毛尖产于河南信阳，属炒青绿茶。外形细、圆、光、直、多白毫，色泽翠绿，香气清高带熟栗子香，滋味醇厚鲜爽，汤色嫩绿明亮。以"细圆光直多白毫，香高味浓汤色绿"为品质特征，谷雨前采制的"明前""雨前"品质最优。', 70, 5),
(106, 3, '太平猴魁属烘青绿茶，产于安徽黄山太平县（今黄山区）猴坑一带。外形两叶抱芽、扁平挺直、自然舒展，白毫隐伏，有"猴魁两头尖，不散不翘不卷边"之称。香气高爽持久带兰花香，滋味鲜爽醇厚回甘，叶底嫩匀肥厚。', 66, 6),
(107, 3, '安吉白茶虽名为"白茶"，实为绿茶——因茶树品种"白叶一号"在低温期叶绿素缺失、叶色玉白而得名，加工工艺是杀青绿茶工艺。氨基酸含量高达 6% 以上（普通绿茶约 2-3%），因此滋味特别鲜爽，几乎无苦涩。', 66, 7),
(108, 3, '白茶属微发酵茶，工艺极简，仅萎凋与干燥两步，不炒不揉。按采摘标准分为白毫银针（单芽）、白牡丹（一芽一二叶）、贡眉与寿眉（一芽二三叶及叶片）。新白茶毫香清鲜、汤色杏黄；陈放后转化出枣香、药香，有"一年茶三年药七年宝"之说。', 76, 8),
(109, 3, '白毫银针产于福建福鼎、政和，全由肥壮单芽制成，满披白毫、挺直如针、色白如银。汤色浅杏黄清澈，毫香显露，滋味清鲜醇和。因产量稀少、采摘期短（清明前后十余天），为白茶中最高等级。', 62, 9),
(110, 3, '白牡丹取一芽一二叶，绿叶夹银白色毫心，冲泡后绿叶托嫩芽，形似花朵故名。汤色杏黄或橙黄清澈，毫香显且带花香，滋味清甜醇爽，是白茶中性价比较高的品类。', 56, 10),
(111, 3, '寿眉与贡眉采一芽二三叶或抽针后的叶片制成，叶张稍肥嫩、芽叶连枝，梗叶相间。汤色橙黄，滋味醇厚，陈化后易出枣香与药香，是老白茶与煮茶的主要原料。寿眉产量最大，价格亲民。', 60, 11),
(112, 3, '黄茶属轻发酵茶，关键工艺是"闷黄"——杀青后趁热堆积或用纸包裹，使茶多酚轻度氧化、叶绿素破坏，形成"黄汤黄叶"特征。按鲜叶老嫩分黄芽茶（君山银针、蒙顶黄芽）、黄小茶、黄大茶（霍山黄大茶）。', 68, 12),
(113, 3, '君山银针产于湖南岳阳洞庭湖君山岛，属黄芽茶。外形芽头肥壮挺直、满披茸毛、色金黄光亮。冲泡时芽尖冲向水面，悬空竖立，继而徐徐下沉，三起三落，为茶中奇观。汤色橙黄明亮，香气清鲜，滋味甜爽。', 70, 13),
(114, 3, '乌龙茶（青茶）属半发酵茶，工艺为萎凋、做青、炒青、揉捻、烘焙。做青是形成乌龙茶品质的关键——通过摇青与晾青交替，使叶片边缘摩擦破损、发生酶促氧化，形成"绿叶红镶边"。香气馥郁，兼具绿茶清香与红茶醇厚。', 76, 14),
(115, 3, '铁观音原产福建安溪，属闽南乌龙。传统清香型铁观音外形卷曲紧结、沉重似铁，色泽砂绿，有"蜻蜓头、螺旋体、青蛙腿"之说。香气清高带兰花香（"观音韵"），滋味醇厚甘鲜，七泡有余香。浓香型经烘焙，带火香与米香。', 78, 15),
(116, 3, '武夷岩茶属闽北乌龙，产于福建武夷山。因茶树生长于岩缝之中，形成独特"岩韵"——香气辛锐、滋味醇厚、回甘明显、喉韵深长。代表品种有大红袍、肉桂、水仙、白鸡冠、铁罗汉、水金龟、半天妖。', 70, 16),
(117, 3, '大红袍是武夷岩茶中最著名的名丛，母树仅存六株于武夷山九龙窠绝壁。现市售大红袍多为母树无性繁殖（纯种）或以肉桂、水仙拼配（商品大红袍）。品质特征为香气馥郁带兰花香、岩韵明显、汤色橙黄明亮、耐冲泡。', 72, 17),
(118, 3, '凤凰单丛产于广东潮州凤凰山，属广东乌龙。按香型分为蜜兰香、黄枝香、芝兰香、桂花香、玉兰香、姜花香、夜来香、茉莉香、杏仁香、肉桂香十大香型。香气高锐持久，滋味浓醇鲜爽，回甘力强，极耐冲泡。', 70, 18),
(119, 3, '铁观音与武夷岩茶的区别：铁观音属闽南乌龙，发酵度较低（约 15-30%），清香型为主，香气清高带兰花香，汤色金黄；武夷岩茶属闽北乌龙，发酵度较高（约 30-60%），焙火重，讲究"岩骨花香"，汤色橙红，滋味更醇厚且带火功香。', 80, 19),
(120, 3, '红茶属全发酵茶，鲜叶经萎凋、揉捻、发酵、干燥而成。发酵使茶多酚氧化生成茶黄素、茶红素，形成"红汤红叶"特征。香气甜醇带花果香或蜜香，滋味醇厚甘甜，性温，适合冬季饮用与调饮。', 66, 20),
(121, 3, '正山小种产于福建武夷山桐木关，是世界最早的红茶（约 16 世纪末），被称为"红茶鼻祖"。传统工艺用松柴熏焙，形成独特的松烟香与桂圆汤味。现分烟小种（传统熏焙）与无烟小种（近年主流）。', 68, 21),
(122, 3, '金骏眉是 2005 年创制的顶级红茶，产于武夷山桐木关。全由单芽制成，数万颗芽头才得一斤干茶。外形细小紧密、金毫显露，汤色金黄，香气带花果香、蜜香与桂圆香，滋味鲜活甘爽。因原料珍稀，价格昂贵，市面仿品极多。', 76, 22),
(123, 3, '祁门红茶简称"祁红"，产于安徽祁门一带，是世界三大高香红茶之一。外形条索紧细苗秀，色泽乌润，香气浓郁带玫瑰花香（"祁门香"），滋味鲜醇甘厚，汤色红艳明亮。适合清饮，加奶后香气不减，为英式下午茶常用茶。', 74, 23),
(124, 3, '滇红产于云南，以大叶种茶树鲜叶制成。芽叶肥壮、金毫显露，汤色红浓明亮，香气高锐带蜜香，滋味浓强鲜爽、刺激性较强。因内含物质丰富，极耐冲泡，常用于调饮奶茶。代表有滇红工夫、金针、金螺。', 68, 24),
(125, 3, '黑茶属后发酵茶，关键工序是渥堆——通过微生物参与发酵，使茶叶内含物发生深刻转化。特征为色泽黑褐、汤色红浓、滋味醇厚陈香。主要品类有湖南安化黑茶、广西六堡茶、云南普洱茶（熟茶）、湖北青砖、四川边茶。', 72, 25),
(126, 3, '普洱茶分生茶与熟茶。生茶以云南大叶种晒青毛茶为原料，自然陈化，新茶汤色黄绿、滋味强烈、带青味，随年份转化出陈香、汤色转红。熟茶经人工渥堆发酵，汤色红浓、滋味醇厚顺滑、带陈香，可即时饮用。', 70, 26),
(127, 3, '六堡茶产于广西梧州苍梧县六堡镇，属黑茶。以"红、浓、陈、醇"著称，带独特槟榔香。历史上通过"茶船古道"远销南洋，因耐储存、解暑祛湿，成为东南亚华人矿工的日常饮品。', 60, 27),
(128, 3, '安化黑茶产于湖南安化，传统品类有"三尖"（天尖、贡尖、生尖）、"三砖"（茯砖、黑砖、花砖）、"一卷"（千两茶）。其中茯砖茶在渥堆后需"发花"——生长冠突散囊菌（俗称"金花"），使茶汤更醇和并带独特菌花香。', 72, 28),
(129, 3, '六大茶类发酵度与茶性对照：绿茶不发酵、性寒；白茶微发酵、性凉（老白茶转平）；黄茶轻发酵、性凉；乌龙茶半发酵、性平；红茶全发酵、性温；黑茶后发酵、性温和。体质偏寒宜红茶与黑茶，体质偏热宜绿茶与白茶。', 76, 29);
INSERT INTO `kb_chunk` (`id`, `document_id`, `content`, `token_count`, `chunk_index`) VALUES
(130, 4, '绿茶冲泡要点：水温 80-85℃，切忌沸水直冲——高温会烫熟茶叶、破坏叶绿素，使茶汤发黄发苦。投茶量约 3 克配 150 毫升水。建议用玻璃杯或白瓷盖碗，便于观赏茶叶舒展与汤色。第一泡约 1 分钟即可饮用。', 74, 0),
(131, 4, '绿茶三种投茶法：①上投法——先注水后投茶，适合细嫩名茶（碧螺春、信阳毛尖），茶叶徐徐下沉、观赏性最佳；②中投法——先注三分之一水、投茶、再注满，适合龙井等扁平茶；③下投法——先投茶后注水，适合普通绿茶与老叶茶。', 78, 1),
(132, 4, '红茶冲泡要点：水温 90-95℃，投茶量约 3-5 克配 150 毫升水，冲泡时间 3-5 秒出汤（工夫红茶宜快出汤，避免苦涩）。宜用白瓷盖碗或紫砂壶。清饮可品其花果蜜香；调饮可加牛奶、柠檬、蜂蜜。', 70, 2),
(133, 4, '乌龙茶冲泡要点：必须用沸水（100℃），因为乌龙茶发酵度较高、叶片厚实，低温无法激发香气。投茶量大（约 7-8 克配 100 毫升水，约占壶容三分之一至二分之一）。用紫砂壶或盖碗，快冲快出，可冲泡七次以上。', 74, 3),
(134, 4, '乌龙茶"工夫泡法"步骤：①温壶烫杯；②投茶（壶容 1/3 至 1/2）；③洗茶（快速注水后立即倒出，唤醒茶叶）；④高冲注水；⑤刮沫淋壶；⑥出汤（首泡约 15-30 秒，之后逐泡延长 5-10 秒）；⑦分茶入杯，先闻香后品味。', 80, 4),
(135, 4, '白茶冲泡要点：新白茶（白毫银针、白牡丹）水温 85-90℃，用玻璃杯或盖碗，可观赏芽叶舒展。老白茶（寿眉、老贡眉）宜用沸水冲泡或煮饮，煮茶时投茶 5 克配 500 毫升水，煮沸后转小火慢煮 3-5 分钟，可充分释放陈香与药香。', 80, 5),
(136, 4, '黑茶冲泡要点：必须用沸水（100℃），且建议先"洗茶"两次以去除渥堆陈味、唤醒茶性。投茶量约 5-8 克配 150 毫升水，可用紫砂壶或盖碗。老茶、紧压茶（茶砖、千两茶）适合煮饮，煮出的茶汤更醇厚顺滑。', 72, 6),
(137, 4, '普洱茶冲泡要点：生茶水温 95-100℃，投茶 5-7 克，快出汤（前几泡 5-10 秒），避免闷出苦涩；熟茶水温 100℃，可适当闷泡（10-20 秒）以激发陈香。建议用紫砂壶（熟茶）或盖碗（生茶，便于观察汤色变化与判断年份）。', 76, 7),
(138, 4, '盖碗泡茶的优势：①材质为白瓷，不吸香不串味，能真实反映茶叶本味；②碗口宽阔便于闻香、观汤色、看叶底；③出汤快、易控制时间；④适合评审与日常冲泡，六大茶类通用。缺点是需练习手法，避免烫手。', 70, 8),
(139, 4, '紫砂壶泡茶的优势与局限：双气孔结构使其透气而不透水，能吸附茶香并"养壶"，长期使用后即使注白水也有茶香。因吸附性强，必须"一壶一茶"避免串味。局限：不适合冲泡绿茶与清香型乌龙（会吸附其清扬香气、闷熟茶叶）。', 74, 9),
(140, 4, '水质对茶汤的影响：古人云"水为茶之母"。首选山泉水（矿物质含量适中、活性好）；次选纯净水（稳定但略平）；自来水需煮沸后静置去氯。硬水（钙镁离子高）会使茶汤浑浊、滋味发涩、香气沉闷；软水泡茶汤色明亮、香气清扬。', 74, 10),
(141, 4, '泡茶水温通则：芽叶细嫩的名优绿茶 80-85℃；普通绿茶 85-90℃；黄茶 85-90℃；白茶（新）85-90℃、（老）100℃；乌龙茶 100℃；红茶 90-95℃；黑茶与普洱 100℃。判断水温可看水沸状态：蟹眼（80℃）、鱼眼（90℃）、腾波鼓浪（100℃）。', 86, 11),
(142, 4, '茶叶"洗茶"的作用与争议：洗茶（温润泡）可去除表面浮尘、降低仓储陈味、唤醒茶性，对黑茶、老白茶、陈年乌龙尤为必要。但对细嫩绿茶与高等级白茶，洗茶会流失氨基酸与香气，建议跳过或仅用极快的一冲。', 74, 12),
(143, 4, '茶汤审评的四项因子：①香气——热嗅辨纯异、温嗅辨香型、冷嗅辨持久性；②汤色——看色度、亮度、清浊；③滋味——品浓淡、醇涩、鲜爽、回甘与喉韵；④叶底——看嫩度、匀整度、色泽与活性。专业审评还需加"外形"一项。', 78, 13),
(144, 4, '茶汤"回甘"与"生津"：回甘指饮后口腔由苦转甜的转化感，源于茶多酚与唾液蛋白结合后的收敛消退；生津指两颊、舌底分泌唾液，是茶汤中糖类、氨基酸与有机酸共同刺激的结果。二者与"喉韵"（茶汤下咽后喉部持久的甘润感）共同构成好茶的体感层次。', 88, 14),
(145, 4, '茶叶"苦涩"的来源：苦味主要来自咖啡碱、茶皂素与部分黄酮类；涩感来自茶多酚（儿茶素类）与唾液蛋白结合产生的收敛作用。苦涩本身不是缺点——关键在于能否"化得开"：优质茶苦涩入口后迅速转化为回甘，劣质茶则苦涩滞留、化不开。', 82, 15),
(146, 4, '陈香与霉味的区别：陈香是茶叶在良好仓储中经缓慢氧化与微生物转化产生的醇和香气（带木香、药香、枣香），闻之舒适；霉味是受潮霉变产生的刺鼻、闷浊、带土腥或酸腐的气味，茶汤浑浊发暗。前者是价值，后者是变质，务必区分。', 82, 16),
(147, 4, '不同茶类的耐泡次数参考：细嫩绿茶 2-3 泡；黄茶 2-3 泡；新白茶 3-5 泡、老白茶（煮）可 8 泡以上；清香乌龙 5-7 泡；浓香/岩茶 7-10 泡；红茶 3-5 泡；黑茶与普洱 8-15 泡（古树茶可达 20 泡）。耐泡度与茶叶内含物丰富度、投茶量、水温相关。', 86, 17),
(148, 4, '冷泡茶的做法与特点：用常温水或冷水（约 4-10℃）浸泡茶叶 4-8 小时（冷藏过夜更佳），茶水比约 1:100。低温萃取使咖啡碱与茶多酚析出减少，因此苦涩度低、甘甜感突出、咖啡因含量较低，适合夏季与对咖啡因敏感人群。绿茶、白茶、乌龙茶均适合冷泡。', 92, 18),
(149, 4, '煮茶的适用茶类与方法：适合黑茶（茯砖、六堡）、老白茶（寿眉、贡眉）、陈年普洱与陈皮茶。方法：投茶 5-8 克配 500-800 毫升水，冷水入壶同煮，水沸后转小火煮 3-5 分钟即可出汤；可续煮 2-3 次。注意不宜久煮，否则茶汤过浓发苦。', 82, 19),
(150, 4, '调饮茶常见搭配：红茶 + 牛奶（奶茶）、红茶 + 柠檬（柠檬红茶）、绿茶 + 薄荷、乌龙茶 + 蜂蜜、普洱茶 + 菊花/陈皮/玫瑰。注意：加奶会掩盖细嫩茶的香气，因此调饮宜选滋味浓强的滇红、祁红或碎茶，不宜用名优绿茶。', 74, 20),
(151, 4, '茶点的搭配原则："甜配绿、酸配红、瓜子配乌龙"。绿茶清鲜，宜配清淡微甜的茶点（绿豆糕、龙须酥）以免盖过茶香；红茶醇厚，宜配带酸味的点心（柠檬派、果酱饼干）以平衡口感；乌龙茶香气高，宜配咸香坚果（瓜子、花生）以衬茶香。', 84, 21),
(152, 4, '品茶的环境与心境：古人讲究"茶宜精舍、宜云林、宜松月、宜晏坐"（明·许次纾《茶疏》）。品茶环境宜安静、通风、无异味，避免香水、烟味、油烟干扰嗅觉。器皿宜素雅（白瓷、青瓷、紫砂），光线宜柔和自然，便于观察汤色与叶底。', 82, 22),
(153, 4, '茶汤浓度与投茶量换算：日常冲泡茶水比参考——绿茶 1:50（3g/150ml）；红茶 1:50 至 1:60；乌龙茶 1:15 至 1:20（7g/100-140ml，因需多次冲泡）；白茶 1:20 至 1:30；黑茶/普洱 1:20 至 1:25。口味浓淡可在此基础上增减 20%。', 82, 23),
(154, 4, '水质硬度与茶汤表现的实测结论：用 TDS 检测笔测量，泡茶理想 TDS 为 30-80 mg/L。TDS 低于 10（纯净水）茶汤清亮但香气偏薄；TDS 高于 150（硬水）茶汤易浑浊、滋味发涩、香气沉闷，且易在茶具上结水垢。若本地自来水 TDS 过高，建议用净水器过滤后再泡。', 96, 24);
INSERT INTO `kb_chunk` (`id`, `document_id`, `content`, `token_count`, `chunk_index`) VALUES
(155, 5, '绿茶选购要点：一看外形——条索紧结匀整、色泽嫩绿或翠绿有光泽；二闻香气——清高纯正、无异味；三看汤色——清亮不浑浊；四品滋味——鲜爽回甘、不苦涩。新茶（当年春茶）香气最佳，隔年绿茶香气明显衰减。', 70, 0),
(156, 5, '龙井茶的等级与产区：按产区分为西湖产区（核心，狮龙云虎梅）、钱塘产区、越州产区。只有西湖产区的才能叫"西湖龙井"，其余为"龙井茶"。按采摘时间分"明前"（清明前，最贵）、"雨前"（谷雨前）、"雨后"。明前茶芽叶细嫩、产量少、价格高；雨前茶滋味更浓、性价比更好。', 92, 1),
(157, 5, '明前茶与雨前茶的区别：明前茶为清明节前采制，气温低、芽叶细嫩、氨基酸含量高、茶多酚相对低，因此滋味鲜爽甘甜、几乎无苦涩，但产量稀少、价格高昂；雨前茶为清明至谷雨间采制，气温回升、芽叶稍大、茶多酚含量略高，滋味更浓醇、耐泡度更好，价格相对亲民。', 96, 2),
(158, 5, '白茶的年份与价值：白茶有"一年茶、三年药、七年宝"之说。新白茶性凉、毫香清鲜；陈放 3 年以上转化出枣香、药香，茶性转平和，适合煮饮；7 年以上为稀有老茶，汤色橙红透亮、滋味醇厚顺滑。选购老白茶需注意辨别做旧茶——做旧茶色泽死黑、香气闷浊、汤色暗沉。', 96, 3),
(159, 5, '普洱茶选购：①看原料——古树茶（树龄百年以上）与台地茶（密植茶园）品质与价格差距大；②看年份——生茶需陈化，熟茶可即时饮；③看仓储——干仓（湿度低、转化慢、香气纯正）优于湿仓（湿度高、转化快但易霉变）；④看外形——条索肥壮、色泽油润、无霉斑。', 86, 4),
(160, 5, '如何辨别染色茶与加香茶：染色绿茶（常见于劣质碧螺春）用湿纸巾擦拭会掉色；加香茶（如加香铁观音）干茶香气刺鼻浓烈、不自然，冲泡 2-3 泡后香气骤减甚至出现水味。天然茶叶香气是内源性的，随冲泡次数递减平缓，且冷嗅（茶汤冷却后）仍有留香。', 88, 5),
(161, 5, '茶叶储存的五大敌人：①光线——紫外线加速叶绿素与脂类氧化；②高温——每升高 10℃ 氧化速率约翻倍；③氧气——氧化茶多酚与香气物质；④潮湿——含水率超过 7% 易霉变；⑤异味——茶叶多孔结构极易吸附周围气味（如樟脑、调料、化妆品）。', 84, 6),
(162, 5, '绿茶与清香型乌龙的储存：必须密封、避光、防潮、低温。最佳方式是分装成小份（约 50-100 克）抽真空或加脱氧剂，放入冰箱冷冻室（-18℃）或冷藏室（0-5℃）。注意：从冰箱取出后需等茶罐恢复至室温再开封，否则冷凝水会使茶叶受潮。', 84, 7),
(163, 5, '红茶与浓香型乌龙的储存：常温、密封、避光、干燥即可，无需冷藏。红茶全发酵、内含物相对稳定，常温可存 1-2 年；浓香型乌龙（武夷岩茶、炭焙铁观音）经焙火后水分低，常温密封可存 2-3 年，且隔年"退火"后滋味更醇和。', 76, 8),
(164, 5, '黑茶与白茶的储存：与绿茶相反，这两类需要"呼吸"与后发酵转化。宜用透气材质（棉纸、竹篓、陶罐）包装，存放于阴凉、干燥、通风、无异味处，避免密封死。适宜湿度 60-70%、温度 20-28℃。注意避免与有异味物品同放，且定期检查有无霉变。', 84, 9),
(165, 5, '茶叶含水率的判断与标准：国标要求绿茶含水率 ≤7%，黑茶 ≤14%。简易判断法：抓一把茶叶紧握，松手后若能自然散开且有清脆"沙沙"声，说明较干；若成团不散、手感柔软，说明含水率偏高、易霉变。含水率高的茶应尽快烘干或优先饮用。', 76, 10),
(166, 5, '冰箱存茶的注意事项：①必须密封——茶叶吸附性极强，与食物同放会串味；②分装小份——避免反复取用造成温差结露；③绿茶、清香乌龙适合冷藏，红茶、黑茶、白茶不宜冷藏（低温会抑制后发酵转化）；④从冰箱取出的茶需回温后再开袋。', 78, 11),
(167, 5, '茶叶保质期的真相：绿茶常温约 12 个月（冷藏可延至 18 个月）；红茶 2-3 年；乌龙茶（清香）18 个月、（浓香/岩茶）2-3 年；白茶与黑茶在合适条件下可长期存放（越陈越香，但需定期检查）。"保质期"与"最佳品饮期"不同——绿茶过期后香气衰减但仍可饮用（只要无霉变）。', 96, 12),
(168, 5, '如何判断茶叶是否变质：①闻——出现霉味、酸味、油哈味（脂肪氧化）；②看——干茶发暗、长白霜或绿毛（霉斑）；③摸——手感发软、成团；④泡——茶汤浑浊发暗、滋味寡淡或有异味。出现霉变的茶必须丢弃，不可饮用（霉菌毒素耐高温，冲泡无法去除）。', 88, 13),
(169, 5, '网购茶叶的避坑要点：①警惕"9.9 元包邮古树茶"等价格背离成本的产品；②看生产日期而非"保质期"，绿茶尤重新鲜度；③要求提供检测报告（农残、重金属）；④注意"明前特级"等标签是否有产区与等级标准支撑；⑤优先选择可退换的商家，收到后立即试泡验证。', 88, 14),
(170, 5, '茶叶价格的影响因素：①产区（核心产区 vs 外围）；②采摘时间（明前 > 雨前 > 雨后）；③采摘标准（单芽 > 一芽一叶 > 一芽二叶）；④工艺（手工 vs 机制）；⑤产量与稀有度；⑥品牌与包装。同样叫"龙井"，核心产区明前手工茶与外围产区雨前机制茶价差可达数十倍。', 92, 15),
(171, 5, '春茶、夏茶、秋茶的区别：春茶（3-5 月）内含物丰富、滋味鲜爽，品质最佳；夏茶（6-7 月）气温高、生长快，茶多酚含量高、氨基酸低，滋味苦涩，多用于制作红茶与大宗茶；秋茶（8-10 月）香气高长但滋味较薄，铁观音的"秋香"即指此特点。', 82, 16),
(172, 5, '茶叶的"回潮"与复焙：茶叶受潮后可通过复焙（低温烘干）挽救，温度控制在 60-80℃、时间 20-40 分钟，中途翻动。但复焙会损失部分香气，且仅适用于含水率轻度超标、尚未霉变的茶。已霉变的茶无法通过复焙挽救。', 74, 17),
(173, 5, '散茶与紧压茶的选择：散茶取用方便、转化快（与空气接触面积大），但占空间、易受潮；紧压茶（茶饼、茶砖、沱茶）体积小、利于长期陈化与运输，且内部转化缓慢均匀，是黑茶与普洱的传统形态。选购时注意茶饼是否松紧适度（过紧不利转化，过松易碎）。', 86, 18),
(174, 5, '送礼选茶的考虑因素：①收礼人饮茶习惯（不常喝茶者宜选红茶或白茶，接受度高；老茶客宜选岩茶、普洱）；②保质与储存难度（绿茶需冷藏，不宜长途送礼）；③包装体面度；④预算与性价比。搭配建议：绿茶礼盒适合春季、长辈；红茶礼盒四季皆宜、商务场合稳妥。', 90, 19);
INSERT INTO `kb_chunk` (`id`, `document_id`, `content`, `token_count`, `chunk_index`) VALUES
(175, 6, '紫砂壶的"开壶"方法：新壶需去除烧制残留的土腥味与窑灰。步骤：①清水洗净壶内外；②放入锅中加清水没过壶身，小火煮沸后加入少量茶叶（与日后泡的茶类相同），继续煮 20-30 分钟；③取出自然冷却、晾干。切忌骤冷骤热，以免惊裂。', 82, 0),
(176, 6, '紫砂壶的日常养护（养壶）：①专壶专用——一把壶只泡一类茶，避免串味；②用后及时清理——倒净茶渣，用清水冲洗，切勿用洗洁精；③自然晾干——倒扣于通风处阴干，忌暴晒或用布用力擦拭；④定期"淋壶"——泡茶时用茶汤浇淋壶身，长期使用形成温润包浆。', 88, 1),
(177, 6, '紫砂泥料的主要类型：①紫泥（紫砂）——最常见，透气性好，适泡普洱、乌龙；②红泥（朱泥）——收缩率大、成品小，适合乌龙茶，聚香性好；③段泥（团泥）——颜色浅黄，透气性最佳，适合绿茶、白茶、黄茶等轻发酵茶；④绿泥——产量稀少，质地较嫩。', 82, 2),
(178, 6, '盖碗的选择：①材质——白瓷最佳（不吸香、易观察汤色），青瓷次之，玻璃便于观赏；②容量——日常 110-150 毫升，评审用 150 毫升标准碗；③器型——碗口外撇便于出汤、不易烫手；④盖与碗的贴合度——过松易漏，过紧易卡。新手建议选厚胎盖碗，散热慢、不易烫手。', 92, 3),
(179, 6, '公道杯（茶海）的作用：将盖碗或壶中的茶汤先倒入公道杯，再分入各品茗杯。作用有三：①均匀茶汤浓度——避免先倒的淡、后倒的浓；②沉淀茶渣；③便于观色闻香。材质以玻璃为佳（可观汤色），白瓷次之，避免使用有色的内壁影响观色。', 82, 4),
(180, 6, '品茗杯的选择与用法：容量宜小（30-50 毫升），便于小口品饮、感受香气与回甘。材质以白瓷、青瓷为佳，内壁必须为白色以便观察汤色。持杯方式：拇指与食指捏杯沿，中指托杯底，称"三龙护鼎"；饮时小口啜入，让茶汤在口腔中铺开以充分接触味蕾。', 88, 5),
(181, 6, '茶滤（滤网）的使用与取舍：用于过滤茶汤中的碎末，使茶汤清澈。材质有金属（不锈钢、银）、陶瓷、棉麻、竹制。注意：细密滤网会过滤掉部分茶毫与内含物质，影响口感层次，因此高等级名优茶（白毫银针、碧螺春）通常不用滤网，直接出汤。', 78, 6),
(182, 6, '铁壶与银壶的适用性：①铁壶——煮水可提升水温并释放微量铁离子，使水质更"软"，适合冲泡老茶与普洱，但不宜煮茶（易生锈、影响茶味）；②银壶——导热极快、水质清甜，适合煮水与煮茶，抑菌性好，但价格昂贵、需定期擦拭保养。', 82, 7),
(183, 6, '玻璃茶具的优势与适用茶类：透明材质便于观赏茶叶在水中舒展、沉浮与汤色变化，特别适合冲泡名优绿茶（龙井、碧螺春）、白茶（白毫银针）与花草茶。缺点是保温性差（水温下降快），因此不适合需要高温冲泡的乌龙茶与黑茶。', 76, 8),
(184, 6, '茶具的清洁禁忌：①忌用洗洁精——残留会污染茶味，且紫砂会吸附化学气味；②忌用钢丝球——会刮伤釉面与紫砂表面；③忌用开水长时间浸泡紫砂——可能致裂；④茶垢不宜过度清洗——白瓷上的茶垢可用小苏打或牙膏轻擦，紫砂的"包浆"应保留。', 82, 9),
(185, 6, '陶瓷茶具的分类：①白瓷——胎质细腻、釉色洁白，不吸香、便于观色，六大茶类通用；②青瓷——釉色青翠温润，以龙泉青瓷、汝窑为代表，适合绿茶与白茶；③青花瓷——白地蓝花，兼具实用与观赏价值；④汝窑/哥窑——开片纹理，讲究"雨过天青色"。', 86, 10),
(186, 6, '茶盘的选择：①材质——竹木（电木、乌金石、紫檀）最常见，石质（端砚石、黑金石）稳重大气，陶瓷便于清洁；②排水方式——嵌入式（盘面开槽排水）整洁但需接管，明式（盘面斜坡直接排入下方水桶）简单实用；③尺寸——按常用茶具数量选择，单人 30×20cm 即可。', 90, 11),
(187, 6, '茶巾的使用与更换：茶巾用于擦拭茶具与桌面，应选吸水性好的棉麻材质。使用时区分"湿巾"（擦拭茶汤）与"干巾"（擦干杯底、防止水渍），避免混用。茶巾需每日清洗晾干，否则易滋生细菌并产生异味，反而污染茶具。', 74, 12),
(188, 6, '紫砂壶"惊裂"的原因与预防：惊裂指壶体因温差骤变而开裂。常见诱因：①冬季用冷水壶直接注入沸水；②开壶时从沸水直接投入冷水；③清洗后立即用高温水冲烫。预防：使用前先用温水"温壶"（内外淋浇温水，再逐步升温），冬季尤须注意。', 82, 13),
(189, 6, '茶具的"养"与"净"的平衡：紫砂讲究养出包浆（茶汤滋养形成的温润光泽），但"养"不等于"脏"——茶垢堆积过厚会滋生细菌、影响茶味。正确做法：每次用后清水冲洗、阴干，让包浆自然累积；若出现异味，可用清水煮沸后自然冷却，恢复茶壶"呼吸"。', 84, 14);
INSERT INTO `kb_chunk` (`id`, `document_id`, `content`, `token_count`, `chunk_index`) VALUES
(190, 7, '茶的起源：中国是茶的故乡，饮茶始于神农氏（传说"神农尝百草，日遇七十二毒，得荼而解之"）。茶最初作药用，后为食用（羹饮），至唐代转为清饮并形成文化。陆羽《茶经》（约 780 年）是世界第一部茶学专著，标志着中国茶文化的正式形成。', 84, 0),
(191, 7, '陆羽与《茶经》：陆羽被尊为"茶圣"，《茶经》共三卷十节，系统论述茶的起源、采制工具、制茶方法、煮茶器具、煮茶方法、饮茶方式、茶事史料、茶叶产区与茶具省略等，是世界茶学开山之作。书中提出"茶之为饮，发乎神农氏，闻于鲁周公"。', 84, 1),
(192, 7, '唐代煎茶法：将茶饼碾成末，水沸后先加盐调味，再投入茶末，用竹夹搅动，待"沫饽"（茶汤表面浮沫）生成后分盛饮用。讲究"三沸"——一沸如鱼目、二沸如涌泉连珠、三沸如腾波鼓浪，认为三沸之后水老不可食。', 78, 2),
(193, 7, '宋代点茶法与斗茶：将茶末置于盏中，注入少量沸水调成膏状，再用茶筅击拂（快速搅拌）使茶汤表面形成细腻持久的白色沫饽，以"咬盏"（沫饽紧贴盏壁不散）为佳。斗茶比较沫饽的颜色与持久度，是宋代文人的流行雅事，后传入日本演变为抹茶道。', 92, 3),
(194, 7, '明清泡茶法的确立：明太祖朱元璋于洪武二十四年（1391 年）"罢造龙团，惟采芽茶以进"，废除饼茶进贡、改贡散茶，使饮茶方式从碾末煮饮转向沸水冲泡散茶。这一变革奠定了现代泡茶法的基础，也促进了紫砂壶与盖碗的兴起。', 82, 4),
(195, 7, '中国茶文化的四大流派：①文人茶——重精神意境，讲究"精行俭德"；②宫廷茶——重礼仪排场，如宋代贡茶与清代三清茶宴；③宗教茶——禅宗"茶禅一味"、道家"天人合一"；④民间茶——重实用与社交，如潮汕工夫茶、成都盖碗茶、北京大碗茶。', 88, 5),
(196, 7, '"茶禅一味"的含义：源于宋代禅宗，指茶道与禅修在精神上的相通——茶的清苦、回甘与静心品饮的过程，契合禅宗"明心见性"的修行方式。唐代赵州从谂禅师"吃茶去"的公案，成为禅茶文化的经典表达。日本茶道（千利休"和敬清寂"）亦源于此。', 88, 6),
(197, 7, '茶马古道：起于唐宋、盛于明清，以云南、四川为起点，经青藏高原至印度、尼泊尔，用茶叶交换马匹的贸易通道。因藏区以肉食为主、需茶助消化，而内地需马匹，形成"茶马互市"。这条古道促进了民族交流与茶文化传播，也是黑茶（砖茶）压制成型的动因之一。', 92, 7),
(198, 7, '海上茶路与茶传世界：中国茶在唐宋时期传入日本、朝鲜；17 世纪经荷兰东印度公司传入欧洲，1657 年伦敦出现首家茶馆。英国因茶叶贸易逆差发动鸦片战争，并在印度阿萨姆、锡兰（斯里兰卡）开辟茶园。如今茶是世界三大无酒精饮料之一。', 90, 8),
(199, 7, '潮汕工夫茶：流行于广东潮汕地区，是中国茶道的代表流派之一。特点：①器具精巧——"四宝"为玉书碨（烧水壶）、潮汕炉（风炉）、孟臣罐（紫砂小壶）、若琛瓯（小茶杯）；②高冲低斟、刮沫淋盖、关公巡城、韩信点兵；③选用凤凰单丛，小壶小杯、浓香耐泡。', 92, 9),
(200, 7, '潮汕工夫茶"关公巡城"与"韩信点兵"：前者指分茶时按顺序循环向各杯注汤，使每杯茶汤浓淡一致（如关公巡视城池）；后者指最后将壶中残余茶汤逐滴均匀分配至各杯（如韩信点兵，多多益善），确保每杯茶汤分量与浓度均衡。', 84, 10),
(201, 7, '成都盖碗茶：流行于四川成都，以盖碗冲泡，配竹椅、方桌与茶馆文化。盖碗由茶盖、茶碗、茶托组成，寓意"天、地、人"三才。成都茶馆兼具饮茶、社交、听书、掏耳朵等功能，是市井文化的代表。', 76, 11),
(202, 7, '日本茶道（茶之汤）：由宋代点茶法传入后发展而成，集大成者千利休提出"和敬清寂"四字精神。以抹茶为主，仪式严谨（含怀石料理、炭点前、浓茶、薄茶等程序），强调"一期一会"——每次相聚都独一无二，应当珍惜。', 82, 12),
(203, 7, '英式下午茶：源于 19 世纪英国贝德福德公爵夫人安娜，因午餐与晚餐间隔过长而在下午 4-5 点加餐，逐渐演变为社交风尚。分 Low Tea（矮桌，以茶与点心为主）与 High Tea（高桌，含肉食，实为工人阶级晚餐）。传统饮用祁门、大吉岭、阿萨姆等红茶，加奶或柠檬。', 96, 13),
(204, 7, '中国四大茶区：①江南茶区（长江中下游，产绿茶、黄茶、黑茶，如龙井、碧螺春、黄山毛峰）；②江北茶区（长江以北，产绿茶，如信阳毛尖）；③西南茶区（云贵川，产红茶、黑茶、普洱，茶树资源最丰富）；④华南茶区（闽粤桂台，产乌龙茶、红茶、白茶，如铁观音、大红袍、白毫银针）。', 98, 14);
INSERT INTO `kb_chunk` (`id`, `document_id`, `content`, `token_count`, `chunk_index`) VALUES
(205, 8, '茶叶的主要功能成分：①茶多酚（占干重 18-36%）——抗氧化、清除自由基；②咖啡碱（2-5%）——提神、促进代谢；③茶氨酸（1-2%）——放松神经、改善注意力；④茶多糖——调节血糖；⑤维生素 C、E 与矿物质（钾、氟、锰）。这些成分共同构成茶的保健基础。', 90, 0),
(206, 8, '茶多酚的抗氧化作用：茶多酚中的儿茶素类（尤其是 EGCG）具有强抗氧化活性，能清除自由基、抑制脂质过氧化、螯合金属离子。体外与动物实验显示其对心血管、代谢与肿瘤有一定保护作用。但需注意：人体临床试验证据尚不充分，不可替代药物治疗。', 92, 1),
(207, 8, '咖啡碱的提神机理与含量差异：咖啡碱通过阻断腺苷受体（腺苷是促进睡眠的神经递质）来提升警觉性。含量受茶类与冲泡影响：红茶与普洱熟茶（发酵后咖啡碱与茶黄素络合）刺激性较低；绿茶与新白茶咖啡碱析出较快。冷泡可显著降低咖啡碱析出量。', 88, 2),
(208, 8, '茶氨酸的独特作用：茶氨酸是茶叶特有的游离氨基酸，能通过血脑屏障，促进 α 脑波产生（与放松而清醒的状态相关），并可拮抗咖啡碱的过度兴奋。这就是"喝茶提神却不亢奋"的原因——咖啡碱与茶氨酸的协同，形成茶特有的"清醒的平静"。', 86, 3),
(209, 8, '不同茶类的咖啡因含量参考（每 200 毫升，约 2-3 克干茶）：绿茶约 20-45 毫克；红茶约 40-70 毫克；乌龙茶约 30-50 毫克；白茶（新）约 15-30 毫克；普洱熟茶约 30-50 毫克。对比：一杯咖啡（200 毫升）约 80-120 毫克。茶因需冲泡析出，通常低于同体积咖啡。', 98, 4),
(210, 8, '饮茶的适宜时间与禁忌：①不宜空腹饮浓茶——刺激胃酸分泌，易致胃部不适；②不宜睡前 3 小时饮浓茶——影响入睡；③不宜用茶送服药物——鞣酸与生物碱可能与药物结合影响吸收（尤其铁剂、镇静剂、部分抗生素）；④不宜饮隔夜茶与过浓茶。', 84, 5),
(211, 8, '哪些人群应限制饮茶：①孕妇与哺乳期女性——咖啡因可通过胎盘与乳汁，建议每日咖啡因摄入低于 200 毫克并选淡茶；②缺铁性贫血者——鞣酸抑制非血红素铁吸收，应餐后 1 小时再饮；③严重失眠与焦虑者——减少咖啡因摄入；④胃溃疡与胃食管反流者——避免浓茶与空腹饮茶。', 92, 6),
(212, 8, '茶叶与铁吸收的关系：茶中的鞣酸（单宁）会与非血红素铁（植物性铁源，如菠菜、豆类）结合形成不溶性复合物，抑制其吸收。但对血红素铁（肉类中的铁）影响较小。建议：贫血者服药或进食富铁食物前后 1 小时内避免饮茶，且可选发酵度高的红茶（鞣酸相对较低）。', 92, 7),
(213, 8, '喝茶减肥的科学依据与局限：茶多酚与咖啡碱可协同促进脂肪氧化、提高基础代谢率（有研究显示可提升 3-4%），但对体重的长期影响有限，且需配合饮食控制与运动。市售"减肥茶"多含泻药成分（如番泻叶），通过脱水造成体重下降的假象，不宜长期饮用。', 90, 8),
(214, 8, '氟与牙齿健康：茶叶是天然富氟植物，尤其老叶与砖茶含氟量高（可达 100-300 mg/kg）。适量氟可增强牙釉质抗酸能力、预防龋齿；但长期大量饮用高氟砖茶（如某些边茶）可能导致氟斑牙甚至氟骨症。建议避免长期以浓砖茶为日常主要饮品。', 90, 9),
(215, 8, '隔夜茶能不能喝：隔夜茶的主要问题是①微生物繁殖（尤其未加盖、夏季高温）；②营养成分氧化（维生素 C 损失、茶多酚氧化导致汤色变深）；③口感变差。若隔夜茶密封冷藏、无浑浊异味，加热后饮用一般无健康风险，但不推荐——营养与风味已明显下降。', 90, 10),
(216, 8, '不同体质如何选茶（中医视角）：①阳虚/虚寒体质——手脚冰凉、怕冷，宜温性茶（红茶、熟普、重焙火乌龙）；②阴虚/燥热体质——易口干、便秘，宜凉性茶（绿茶、新白茶、黄茶）；③痰湿体质——肥胖、舌苔厚腻，宜黑茶、普洱熟茶助消化；④气郁体质——宜花茶（茉莉花茶、玫瑰花茶）疏肝解郁。', 100, 11),
(217, 8, '花草茶与茶叶的区别：花草茶（如玫瑰花茶、菊花茶、洛神花茶）严格说不属于"茶"（非茶树 Camellia sinensis 的叶），而是代用茶或草本饮品。它们通常不含咖啡因，功效侧重特定作用（菊花清肝明目、玫瑰疏肝解郁、洛神花降血压），适合晚间或对咖啡因敏感人群。', 92, 12),
(218, 8, '茶叶的农残与安全：正规渠道的茶叶应符合 GB 2763 农残限量标准。降低风险的做法：①选购有检测报告的品牌茶；②首泡快速倒掉（可去除部分表面残留，但脂溶性农药效果有限）；③优先选择春茶（春季气温低、虫害少、用药少）。需注意：茶汤中农残的实际浸出率通常远低于干茶含量。', 98, 13),
(219, 8, '茶与药膳的常见搭配：①陈皮普洱——理气健脾、助消化；②菊花枸杞茶——清肝明目；③姜茶（红茶 + 生姜）——驱寒暖胃；④桂花乌龙——温中散寒、化痰；⑤薄荷绿茶——清热解暑。注意药膳茶属日常保健范畴，不能替代药物治疗，慢性病患者应咨询医师。', 92, 14);
